import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

describe('ChatOrchestrator beforeSession hook failure (unit)', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const callOrder: string[] = [];
    const error = new Error('beforeSession failed');

    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        callOrder.push('beforeSession');
        throw error;
      },
      onError: async () => {
        callOrder.push('onError');
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const mockProvider: AIProvider = {
      sendMessage: async function* () {
        yield {type: 'text', text: 'hi'};
      },
      generateStructured: async <T>() => ({} as T),
    };

    const orchestrator = createChatOrchestrator(
      mockProvider,
      new PromptBuilder({identity: 'test'}),
      undefined,
      {hooks}
    );

    const session = {sessionId: 's', userId: 'u', entries: [{role: 'user' as const, content: 'h'}]};
    await expect(orchestrator.processMessage(session)).rejects.toThrow('beforeSession failed');

    expect(callOrder).toEqual(['beforeSession', 'onError', 'afterSession']);
  });
});

